"""Schema fuzzing: mutate valid requests and check both models agree."""
import copy, json, random, sys
sys.path.insert(0, '/workspace/dev')
import gen, ref, fast
from diff import compare, candidate_out

MUTS = ['float', 'bool', 'string', 'neg', 'huge', 'drop', 'extra', 'swap', 'type', 'emptylist',
        'nullval', 'nested']

def walk(node, path=()):
    yield node, path
    if isinstance(node, dict):
        for k, v in node.items():
            yield from walk(v, path + (k,))
    elif isinstance(node, list):
        for i, v in enumerate(node):
            yield from walk(v, path + (i,))

def set_at(root, path, value):
    node = root
    for p in path[:-1]:
        node = node[p]
    if path:
        node[path[-1]] = value
    else:
        root = value
    return root

def mutate(request, rng):
    r = copy.deepcopy(request)
    nodes = [(n, p) for n, p in walk(r) if p]
    if not nodes:
        return None
    for _ in range(rng.randint(1, 3)):
        node, path = rng.choice(nodes)
        m = rng.choice(MUTS)
        parent = r
        for p in path[:-1]:
            parent = parent[p]
        key = path[-1]
        if m == 'float':
            parent[key] = 1.5
        elif m == 'bool':
            parent[key] = True
        elif m == 'string':
            parent[key] = 'x'
        elif m == 'neg':
            parent[key] = -3
        elif m == 'huge':
            parent[key] = 10 ** 25
        elif m == 'nullval':
            parent[key] = None
        elif m == 'drop' and isinstance(parent, dict):
            parent.pop(key, None)
        elif m == 'extra' and isinstance(r, dict):
            r['zz'] = 1
        elif m == 'emptylist' and isinstance(parent[key], list):
            parent[key] = []
        elif m == 'nested':
            parent[key] = {'version': 2}
        elif m == 'type':
            parent[key] = [1, 2] if not isinstance(parent[key], list) else 7
        elif m == 'swap' and isinstance(parent, list) and len(parent) > 1:
            parent[key] = parent[0]
    return r

def main(lo, hi):
    fails = 0
    invalid = valid = 0
    for seed in range(lo, hi):
        rng = random.Random(seed * 7919)
        try:
            base = gen.build_request(seed, sessions=2)
        except Exception:
            continue
        r = mutate(base, rng)
        if r is None:
            continue
        data = json.dumps(r, separators=(',', ':'))
        try:
            expect = ref.run_json(data)
        except Exception as exc:
            print('REF CRASH seed', seed, exc)
            fails += 1
            continue
        got = candidate_out(data)
        e = expect.strip(); g = got.strip()
        if e.startswith('{"error"'):
            invalid += 1
        else:
            valid += 1
        same = False
        try:
            same = json.loads(e) == json.loads(g)
        except Exception:
            same = e == g
        if not same:
            fails += 1
            print('FUZZ MISMATCH seed', seed)
            print('  ref ', e[:200])
            print('  cand', g[:200])
            open('/workspace/dev/fail_fuzz.json', 'w').write(data)
    print('fuzz %d..%d invalid=%d valid=%d fails=%d' % (lo, hi, invalid, valid, fails), flush=True)
    return fails

if __name__ == '__main__':
    sys.exit(1 if main(int(sys.argv[1]), int(sys.argv[2])) else 0)
